const output = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];

  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  let text = buffer.toString('utf8');

  // Limpiamos espacios raros o BOM si hubiera
  text = text.replace(/^\uFEFF/, '').trim();

  const json = JSON.parse(text);

  output.push({
    json: {
      source: 'air',
      ...json
    }
  });
}

return output;

let records = $input.all().map(i => i.json);

records = records
  .filter(r => r.datetime)
  .sort((a, b) => new Date(a.datetime) - new Date(b.datetime));

function sumField(records, field) {
  return records.reduce((acc, r) => acc + Number(r[field] || 0), 0);
}

function avgField(records, field) {
  if (records.length === 0) return 0;
  return records.reduce((acc, r) => acc + Number(r[field] || 0), 0) / records.length;
}

function percentage(value, total) {
  if (!total || total === 0) return 0;
  return Number(((Number(value || 0) / total) * 100).toFixed(2));
}

const totalTemperature = sumField(records, 'temperature_2m');
const totalPrecipitation = sumField(records, 'precipitation');
const totalPm10 = sumField(records, 'pm10');
const totalPm25 = sumField(records, 'pm2_5');
const totalCarbonDioxide = sumField(records, 'carbon_dioxide');
const totalUvIndex = sumField(records, 'uv_index');
const totalOlivePollen = sumField(records, 'olive_pollen');
const totalOzone = sumField(records, 'ozone');
const totalMethane = sumField(records, 'methane');

const toxicThresholdPm10 = 10;
const toxicThresholdPm25 = 5;
const toxicThresholdOzone = 90;
const toxicThresholdCo2 = 450;

const enrichedRecords = records.map(r => {
  const isToxic =
    Number(r.pm10 || 0) > toxicThresholdPm10 ||
    Number(r.pm2_5 || 0) > toxicThresholdPm25 ||
    Number(r.ozone || 0) > toxicThresholdOzone ||
    Number(r.carbon_dioxide || 0) > toxicThresholdCo2;

  return {
    datetime: r.datetime,
    date: r.date,
    year: r.year,
    month:r.month,
    day:r.day,
    hour: r.hour,
    city: r.city || 'Madrid',

    temperature_2m: r.temperature_2m,
    precipitation: r.precipitation,
    temperature_percentage_of_day: percentage(r.temperature_2m, totalTemperature),
    precipitation_percentage_of_day: percentage(r.precipitation, totalPrecipitation),

    pm10: r.pm10,
    pm2_5: r.pm2_5,
    carbon_dioxide: r.carbon_dioxide,
    uv_index: r.uv_index,
    olive_pollen: r.olive_pollen,
    ozone: r.ozone,
    methane: r.methane,

    pm10_percentage_of_day: percentage(r.pm10, totalPm10),
    pm2_5_percentage_of_day: percentage(r.pm2_5, totalPm25),
    carbon_dioxide_percentage_of_day: percentage(r.carbon_dioxide, totalCarbonDioxide),
    uv_index_percentage_of_day: percentage(r.uv_index, totalUvIndex),
    olive_pollen_percentage_of_day: percentage(r.olive_pollen, totalOlivePollen),
    ozone_percentage_of_day: percentage(r.ozone, totalOzone),
    methane_percentage_of_day: percentage(r.methane, totalMethane),

    is_toxic: isToxic
  };
});

const toxicHours = enrichedRecords.filter(r => r.is_toxic).length;
const precipitationHours = enrichedRecords.filter(r => Number(r.precipitation || 0) > 0).length;

const summary = {
  total_records: enrichedRecords.length,
  toxic_hours: toxicHours,
  toxic_hours_percentage: enrichedRecords.length ? Number(((toxicHours / enrichedRecords.length) * 100).toFixed(2)) : 0,
  precipitation_hours: precipitationHours,
  precipitation_hours_percentage: enrichedRecords.length ? Number(((precipitationHours / enrichedRecords.length) * 100).toFixed(2)) : 0,
  average_temperature_2m: Number(avgField(enrichedRecords, 'temperature_2m').toFixed(2)),
  total_precipitation: Number(totalPrecipitation.toFixed(2)),
  average_pm10: Number(avgField(enrichedRecords, 'pm10').toFixed(2)),
  average_pm2_5: Number(avgField(enrichedRecords, 'pm2_5').toFixed(2)),
  average_ozone: Number(avgField(enrichedRecords, 'ozone').toFixed(2)),
  max_uv_index: enrichedRecords.length ? Math.max(...enrichedRecords.map(r => Number(r.uv_index || 0))) : 0
};

return enrichedRecords.map(record => {
  const { datetime, ...recordWithoutDatetime } = record;

  return {
    json: {
      summary_total_records: summary.total_records,
      summary_toxic_hours: summary.toxic_hours,
      summary_toxic_hours_percentage: summary.toxic_hours_percentage,
      summary_precipitation_hours: summary.precipitation_hours,
      summary_precipitation_hours_percentage: summary.precipitation_hours_percentage,
      summary_average_temperature_2m: summary.average_temperature_2m,
      summary_total_precipitation: summary.total_precipitation,
      summary_average_pm10: summary.average_pm10,
      summary_average_pm2_5: summary.average_pm2_5,
      summary_average_ozone: summary.average_ozone,
      summary_max_uv_index: summary.max_uv_index,
      ...recordWithoutDatetime
    }
  };
});

const now = new Date();

// Procesamos el día anterior.
// Si queréis procesar el día actual, quitad esta línea.
now.setDate(now.getDate() - 1);

const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');
const day = String(now.getDate()).padStart(2, '0');

const date = `${year}_${month}_${day}`;

return [
  {
    json: {
      year,
      month,
      day,
      date,
      airPrefix: `air/${year}/${month}/${day}/`,
      weatherPrefix: `weather/${year}/${month}/${day}/`,
      outputCsvName: `${year}_${month}_${day}.csv`
    }
  }
];

const output = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];

  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  let text = buffer.toString('utf8');

  text = text.replace(/^\uFEFF/, '').trim();

  const json = JSON.parse(text);

  output.push({
    json: {
      source: 'weather',
      ...json
    }
  });
}

return output;
